def my_transform(grid, n=16):
    """Replace marker color with center-reflection, with horizontal fallback for collisions"""
    # Find marker: least common color
    from collections import Counter
    all_vals = [v for row in grid for v in row]
    counts = Counter(all_vals)
    marker = min(counts, key=counts.get)

    result = [row[:] for row in grid]
    # First pass: collect all cells that are markers AND their center-reflections are also markers
    # This way we can resolve all simultaneously
    for r in range(n):
        for c in range(n):
            if grid[r][c] == marker:
                # Try center reflection
                ref_r, ref_c = n - 1 - r, n - 1 - c
                ref_val = grid[ref_r][ref_c]

                if ref_val != marker:
                    result[r][c] = ref_val
                else:
                    # Collision: both are marker. Try horizontal fallback
                    h_val = grid[r][n - 1 - c]
                    if h_val != marker:
                        result[r][c] = h_val
                    else:
                        # Both center and horizontal are marker...
                        # This shouldn't happen based on our analysis
                        # Just copy center (also marker) - though finding what to do
                        pass
    return result

